input.content:
:root {
  --bg: #f6efe0;
  --bg2: #efe4cd;
  --panel: #fffaf0;
  --ink: #34302a;
  --ink2: #6f675a;
  --line: #e4d8bf;
  --blue: #2f86ff;
  --blue-d: #1f5fc4;
  --red: #f0405a;
  --red-d: #b92640;
  --fruit: #4f9f2c;
  --accent: #ff9f43;
  --radius: 16px;
  font-family: ui-rounded, 'SF Pro Rounded', 'Nunito', system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: var(--ink);
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--bg); }
body { overflow: hidden; }
button, input, select { font: inherit; color: inherit; }

#app {
  height: 100vh;
  display: grid;
  grid-template-columns: 290px minmax(0, 1fr) 340px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: 'top top top' 'ctl stage side';
  gap: 12px;
  padding: 12px;
  background: radial-gradient(1200px 700px at 45% 0%, #fff7e2 0%, var(--bg) 60%, var(--bg2) 100%);
}

.top { grid-area: top; display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
h1 { margin: 0; font-size: 22px; font-weight: 800; letter-spacing: -0.01em; }
h2 { margin: 0; font-size: 14px; font-weight: 800; letter-spacing: 0.01em; }
.transport { display: flex; align-items: center; gap: 8px; }
.presets { display: flex; gap: 6px; flex-wrap: wrap; margin-left: auto; }

button {
  border: 2px solid var(--line);
  background: var(--panel);
  border-radius: 999px;
  padding: 6px 14px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: transform 0.12s, background 0.12s, border-color 0.12s;
}
button:hover { transform: translateY(-1px); border-color: #d2c19e; }
button:active { transform: translateY(1px); }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid #ffbf73; outline-offset: 2px; }
button.primary { background: var(--accent); border-color: #e58628; color: #3b2200; min-width: 76px; }
button.preset.active { background: #34302a; color: #fff; border-color: #34302a; }
.speed { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; color: var(--ink2); }
.speed input { width: 90px; }
.speed output { min-width: 34px; color: var(--ink); }
.clock { font-variant-numeric: tabular-nums; font-weight: 800; background: var(--panel); border: 2px solid var(--line); border-radius: 999px; padding: 5px 12px; font-size: 13px; }

.panel {
  background: var(--panel);
  border: 2px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 2px 0 rgba(120, 90, 30, 0.08);
}

.controls { grid-area: ctl; overflow-y: auto; padding: 8px 14px 14px; }
.controls h3 { margin: 14px 0 6px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; display: flex; align-items: center; gap: 6px; }
.controls h3 i { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.ctl { display: grid; grid-template-columns: 1fr auto; gap: 0 8px; margin: 7px 0; font-size: 12.5px; }
.ctl label { font-weight: 700; color: var(--ink); }
.ctl output { font-variant-numeric: tabular-nums; font-weight: 800; color: var(--ink2); }
.ctl input[type='range'] { grid-column: 1 / -1; width: 100%; margin: 2px 0 0; }
.ctl .tag { font-size: 10px; font-weight: 700; color: #b0651a; background: #ffe7c7; border-radius: 6px; padding: 0 5px; margin-left: 5px; }
input[type='range'] { accent-color: var(--accent); }
.controls.blue input[type='range'] { accent-color: var(--blue); }
.grp-blue input[type='range'] { accent-color: var(--blue); }
.grp-red input[type='range'] { accent-color: var(--red); }
.grp-fruit input[type='range'] { accent-color: var(--fruit); }
.seed-row { display: flex; gap: 6px; grid-column: 1 / -1; }
.seed-row input { flex: 1; min-width: 0; border: 2px solid var(--line); border-radius: 10px; padding: 3px 8px; background: #fff; }

.stage { grid-area: stage; display: grid; grid-template-rows: minmax(0, 1fr) 250px; gap: 12px; min-width: 0; min-height: 0; }
.world-wrap { position: relative; border-radius: 22px; overflow: hidden; border: 2px solid var(--line); background: #e9dcc0; min-height: 0; }
#world { width: 100%; height: 100%; display: block; cursor: grab; touch-action: none; }
#world.dragging { cursor: grabbing; }
.world-hud { position: absolute; left: 12px; top: 12px; display: flex; gap: 6px; }
.chip { background: rgba(255, 250, 240, 0.92); border: 2px solid var(--line); border-radius: 999px; padding: 3px 10px; font-size: 12px; font-weight: 700; display: flex; align-items: center; gap: 6px; }
.chip b { font-variant-numeric: tabular-nums; }
.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.dot.fruit { background: #7cc94a; } .dot.blue { background: var(--blue); } .dot.red { background: var(--red); }
.world-hint { position: absolute; left: 12px; bottom: 10px; font-size: 11.5px; font-weight: 700; color: rgba(60, 50, 30, 0.55); pointer-events: none; }
.banner { position: absolute; left: 50%; top: 14px; transform: translateX(-50%); background: rgba(52, 48, 42, 0.92); color: #fff; padding: 7px 16px; border-radius: 999px; font-weight: 700; font-size: 13px; }

.chart-card { padding: 10px 14px 8px; display: flex; flex-direction: column; min-height: 0; }
.card-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.card-head .sub { font-size: 11px; color: var(--ink2); font-weight: 600; }
.legend { display: flex; gap: 14px; font-size: 12px; font-weight: 700; flex-wrap: wrap; }
.legend.small { font-size: 11px; gap: 10px; padding: 0 12px 10px; }
.lg { display: inline-flex; align-items: center; gap: 5px; }
.lg i { width: 16px; height: 4px; border-radius: 3px; display: inline-block; }
.lg.blue i { background: var(--blue); } .lg.red i { background: var(--red); } .lg.fruit i { background: var(--fruit); }
.lg.dashed i { background: repeating-linear-gradient(90deg, currentColor 0 4px, transparent 4px 7px); }
.lg.blue.dashed { color: var(--blue); } .lg.red.dashed { color: var(--red); }
.lg b { font-variant-numeric: tabular-nums; }
.chart-box { position: relative; flex: 1; min-height: 0; }
.chart-box canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.chart-box.square { flex: none; aspect-ratio: 1.35; margin: 4px 10px 10px; }
.chart-box.short { flex: none; height: 120px; margin: 4px 8px 4px; }

.side { grid-area: side; display: flex; flex-direction: column; gap: 12px; overflow-y: auto; min-height: 0; padding-right: 2px; }
.inspector, .summary { padding: 12px 14px; }
.inspector .empty { color: var(--ink2); font-size: 13px; font-weight: 600; }
.insp-head { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.swatch { width: 26px; height: 32px; border-radius: 50% / 45%; display: inline-block; box-shadow: inset -3px -4px 0 rgba(0, 0, 0, 0.15), inset 3px 3px 0 rgba(255, 255, 255, 0.4); }
.swatch.blue { background: #3a8dff; } .swatch.red { background: #ff4d63; }
.insp-title { font-weight: 800; font-size: 15px; }
.insp-sub { font-size: 12px; color: var(--ink2); font-weight: 600; }
.kv { display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; font-size: 12.5px; margin: 0; }
.kv dt { color: var(--ink2); font-weight: 600; }
.kv dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; text-align: right; }
.bar { height: 9px; border-radius: 6px; background: #eee2c8; overflow: hidden; margin: 2px 0 6px; }
.bar > i { display: block; height: 100%; border-radius: 6px; transition: width 0.1s; }
.bar.energy > i { background: linear-gradient(90deg, #ffb347, #ffd76a); }
.bar.timer > i { background: linear-gradient(90deg, #9b7bff, #d0b8ff); }
.linkish { background: none; border: none; padding: 0; color: var(--blue-d); text-decoration: underline; cursor: pointer; font-weight: 800; border-radius: 4px; }
.linkish:hover { transform: none; }
.summary h2 { margin-bottom: 6px; }
.summary ul { margin: 0 0 8px; padding-left: 18px; font-size: 12.8px; line-height: 1.4; font-weight: 600; }
.summary li { margin: 3px 0; }
.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.stat { background: #f6ecd6; border-radius: 10px; padding: 5px 8px; }
.stat b { display: block; font-size: 15px; font-variant-numeric: tabular-nums; }
.stat span { font-size: 10.5px; color: var(--ink2); font-weight: 700; }
.mini { padding: 10px 4px 0; flex: none; }
.mini .card-head { padding: 0 12px; }

@media (max-width: 1180px) {
  body { overflow: auto; }
  #app { height: auto; grid-template-columns: 1fr; grid-template-areas: 'top' 'stage' 'side' 'ctl'; }
  .stage { grid-template-rows: 520px 250px; }
  .controls { max-height: none; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

